import unittest
from items import first_n


class FirstNTest(unittest.TestCase):
    def test_three(self):
        self.assertEqual(first_n([1, 2, 3, 4, 5], 3), [1, 2, 3])

    def test_zero(self):
        self.assertEqual(first_n([1, 2], 0), [])


if __name__ == '__main__':
    unittest.main()
